window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7c972a368adf454d"]={"versions": [{"id": "FIG-7c972a368adf454d", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm des AUTOSAR-BSW-Konfigurationsmetamodells (ECUC Parameter Configuration Definition gem. <em>AUTOSAR Generic Structure Template</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Modul <strong>SwCluC</strong> (<em>Software Cluster Connection</em>, SWS Release R22-11). Das Modul ermöglicht die Entkopplung und unabhängige Aktualisierbarkeit von Software Clustern (SWC-Gruppierungen/Partitionen) auf einem Classic-AUTOSAR-Steuergerät.</li>\n<li><strong>Technischer Zweck:</strong> Definition der Metamodell-Struktur für Initialisierungs-Events (<code>SwCluCOsProxyDispatcherInitEvent</code>) innerhalb eines OS-Proxy-Task-Dispatchers (<code>SwCluCOsProxyOsTaskDispatcher</code>). Der Dispatcher verarbeitet clusterübergreifende Task- und Event-Aktivierungen über OS-Application- bzw. Speichergrenzen hinweg.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten & Metaklassen:</strong></li>\n<li><strong><code>SwCluCOsProxyOsTaskDispatcher</code></strong> (<code>EcucParamConfContainerDef</code>):</li>\n<li><em>Rolle:</em> Übergeordneter Konfigurationscontainer (Parent). Repräsentiert die Konfigurationsparameter eines dedizierten OS-Tasks, der als Dispatcher für OS-Proxy-Dienste eines Software Clusters fungiert.</li>\n<li><em>Multiplizität:</em> <code>0..*</code> (Optional; mehrere Dispatcher pro ECU/Cluster-Instanz konfigurierbar, z. B. je OS-Application, Core oder Prioritätsebene).</li>\n<li><strong><code>SwCluCOsProxyDispatcherInitEvent</code></strong> (<code>EcucParamConfContainerDef</code>, SWS-ID: <code>ECUC_SwCluC_00153</code>):</li>\n<li><em>Rolle:</em> Untergeordneter Parameter-Container (Child/Subcontainer). Spezifiziert konkrete Initialisierungs-Events, auf die der Proxy-Dispatcher-Task bei System-/Cluster-Start wartet oder die er zur Synchronisation nutzt.</li>\n<li><em>Multiplizität:</em> <code>0..*</code> (Optional; ein Dispatcher kann null, ein oder mehrere Initialisierungs-Events besitzen).</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li><strong>Komposition (<code>+subContainer</code>):</strong> Strenge Existenzabhängigkeit (gefüllte Raute am Container <code>SwCluCOsProxyOsTaskDispatcher</code>). Instanzen von <code>SwCluCOsProxyDispatcherInitEvent</code> existieren ausschließlich im Kontext ihres übergeordneten Dispatcher-Containers und werden mit diesem instanziiert bzw. verworfen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein statisches Konfigurationsmetamodell. Daraus resultiert folgender deterministischer Laufzeitablauf:</p>\n<ol class=\"fig-list\">\n<li><strong>Boot-/Lifecycle-Trigger:</strong> Das Lifecycle-Management (z. B. <code>BswM</code> oder cluster-spezifischer Startcode) startet den Software Cluster und aktiviert den zugeordneten <code>SwCluCOsProxyOsTaskDispatcher</code>.</li>\n<li><strong>Initialisierungs-Synchronisation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Dispatcher-Task blockiert initial in einem <code>WaitEvent(...)</code> auf die über <code>SwCluCOsProxyDispatcherInitEvent</code> konfigurierten Event-Masken.</li>\n<li>Das System (z. B. EcuM, BswM oder der Host-/Master-Cluster) signalisiert die Betriebsbereitschaft der zugrunde liegenden Inter-Cluster-Kommunikationsinfrastruktur (Shared RAM, Mailboxen, OS-Puffer) via <code>SetEvent(...)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dispatch-Freigabe:</strong> Nach Empfang und Validierung des/der Init-Events verlässt der Task den Initialisierungszustand, quittiert das Event (<code>ClearEvent(...)</code>) und wechselt in die operative Dispatching-Schleife zur Weiterleitung von Proxy-Requests an die lokalen Tasks des Ziel-Clusters.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfiguration (ECUC):</strong></li>\n<li>Entwickler müssen sicherstellen, dass jedes über <code>ECUC_SwCluC_00153</code> konfigurierte Init-Event auf ein gültiges <code>OsEvent</code> referenziert, das im korrespondierenden <code>OsTask</code> (dem Dispatcher) im OS-Modul (<code>Os.epc</code>) deklariert ist.</li>\n<li>Eine Multiplizität von <code>0</code> bei <code>SwCluCOsProxyDispatcherInitEvent</code> impliziert, dass der Dispatcher-Task entweder sofort nach <code>ActivateTask()</code> unkonditioniert startfähig ist oder über alternative BswM-Actions gesteuert wird.</li>\n<li><strong>Task-Klassifikation & Ressourceneffizienz:</strong></li>\n<li>Die Verwendung von Events erfordert zwingend einen <strong>Extended Task</strong> im AUTOSAR OS für den Dispatcher (<code>WaitEvent()</code> / <code>SetEvent()</code>). Bei ressourcenkritischen Systemen (RAM-Bedarf für Task-Stacks) ist zu prüfen, ob auf Init-Events verzichtet werden kann, um den Dispatcher als <strong>Basic Task</strong> auszuführen.</li>\n<li><strong>Cluster-Entkopplung & Safety:</strong></li>\n<li>Das Init-Event dient als Barriere gegen Race Conditions beim asynchronen Booten heterogener Software Cluster: Der Proxy-Task nimmt keine operativen Inter-Cluster-Aufrufe entgegen, bevor die durch <code>SwCluCOsProxyDispatcherInitEvent</code> definierte Vorbedingung erfüllt ist.</li>\n</ul>"}, {"id": "FIG-d82dd86b4ae023d8", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm des AUTOSAR-BSW-Konfigurationsmetamodells (ECUC Parameter Configuration Definition gem. <em>AUTOSAR Generic Structure Template</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Modul <strong>SwCluC</strong> (<em>Software Cluster Connection</em>, SWS Release R22-11). Das Modul ermöglicht die Entkopplung und unabhängige Aktualisierbarkeit von Software Clustern (SWC-Gruppierungen/Partitionen) auf einem Classic-AUTOSAR-Steuergerät.</li>\n<li><strong>Technischer Zweck:</strong> Definition der Metamodell-Struktur für Initialisierungs-Events (<code>SwCluCOsProxyDispatcherInitEvent</code>) innerhalb eines OS-Proxy-Task-Dispatchers (<code>SwCluCOsProxyOsTaskDispatcher</code>). Der Dispatcher verarbeitet clusterübergreifende Task- und Event-Aktivierungen über OS-Application- bzw. Speichergrenzen hinweg.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten & Metaklassen:</strong></li>\n<li><strong><code>SwCluCOsProxyOsTaskDispatcher</code></strong> (<code>EcucParamConfContainerDef</code>):</li>\n<li><em>Rolle:</em> Übergeordneter Konfigurationscontainer (Parent). Repräsentiert die Konfigurationsparameter eines dedizierten OS-Tasks, der als Dispatcher für OS-Proxy-Dienste eines Software Clusters fungiert.</li>\n<li><em>Multiplizität:</em> <code>0..*</code> (Optional; mehrere Dispatcher pro ECU/Cluster-Instanz konfigurierbar, z. B. je OS-Application, Core oder Prioritätsebene).</li>\n<li><strong><code>SwCluCOsProxyDispatcherInitEvent</code></strong> (<code>EcucParamConfContainerDef</code>, SWS-ID: <code>ECUC_SwCluC_00153</code>):</li>\n<li><em>Rolle:</em> Untergeordneter Parameter-Container (Child/Subcontainer). Spezifiziert konkrete Initialisierungs-Events, auf die der Proxy-Dispatcher-Task bei System-/Cluster-Start wartet oder die er zur Synchronisation nutzt.</li>\n<li><em>Multiplizität:</em> <code>0..*</code> (Optional; ein Dispatcher kann null, ein oder mehrere Initialisierungs-Events besitzen).</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li><strong>Komposition (<code>+subContainer</code>):</strong> Strenge Existenzabhängigkeit (gefüllte Raute am Container <code>SwCluCOsProxyOsTaskDispatcher</code>). Instanzen von <code>SwCluCOsProxyDispatcherInitEvent</code> existieren ausschließlich im Kontext ihres übergeordneten Dispatcher-Containers und werden mit diesem instanziiert bzw. verworfen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein statisches Konfigurationsmetamodell. Daraus resultiert folgender deterministischer Laufzeitablauf:</p>\n<ol class=\"fig-list\">\n<li><strong>Boot-/Lifecycle-Trigger:</strong> Das Lifecycle-Management (z. B. <code>BswM</code> oder cluster-spezifischer Startcode) startet den Software Cluster und aktiviert den zugeordneten <code>SwCluCOsProxyOsTaskDispatcher</code>.</li>\n<li><strong>Initialisierungs-Synchronisation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Dispatcher-Task blockiert initial in einem <code>WaitEvent(...)</code> auf die über <code>SwCluCOsProxyDispatcherInitEvent</code> konfigurierten Event-Masken.</li>\n<li>Das System (z. B. EcuM, BswM oder der Host-/Master-Cluster) signalisiert die Betriebsbereitschaft der zugrunde liegenden Inter-Cluster-Kommunikationsinfrastruktur (Shared RAM, Mailboxen, OS-Puffer) via <code>SetEvent(...)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dispatch-Freigabe:</strong> Nach Empfang und Validierung des/der Init-Events verlässt der Task den Initialisierungszustand, quittiert das Event (<code>ClearEvent(...)</code>) und wechselt in die operative Dispatching-Schleife zur Weiterleitung von Proxy-Requests an die lokalen Tasks des Ziel-Clusters.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfiguration (ECUC):</strong></li>\n<li>Entwickler müssen sicherstellen, dass jedes über <code>ECUC_SwCluC_00153</code> konfigurierte Init-Event auf ein gültiges <code>OsEvent</code> referenziert, das im korrespondierenden <code>OsTask</code> (dem Dispatcher) im OS-Modul (<code>Os.epc</code>) deklariert ist.</li>\n<li>Eine Multiplizität von <code>0</code> bei <code>SwCluCOsProxyDispatcherInitEvent</code> impliziert, dass der Dispatcher-Task entweder sofort nach <code>ActivateTask()</code> unkonditioniert startfähig ist oder über alternative BswM-Actions gesteuert wird.</li>\n<li><strong>Task-Klassifikation & Ressourceneffizienz:</strong></li>\n<li>Die Verwendung von Events erfordert zwingend einen <strong>Extended Task</strong> im AUTOSAR OS für den Dispatcher (<code>WaitEvent()</code> / <code>SetEvent()</code>). Bei ressourcenkritischen Systemen (RAM-Bedarf für Task-Stacks) ist zu prüfen, ob auf Init-Events verzichtet werden kann, um den Dispatcher als <strong>Basic Task</strong> auszuführen.</li>\n<li><strong>Cluster-Entkopplung & Safety:</strong></li>\n<li>Das Init-Event dient als Barriere gegen Race Conditions beim asynchronen Booten heterogener Software Cluster: Der Proxy-Task nimmt keine operativen Inter-Cluster-Aufrufe entgegen, bevor die durch <code>SwCluCOsProxyDispatcherInitEvent</code> definierte Vorbedingung erfüllt ist.</li>\n</ul>"}, {"id": "FIG-efdb383101a27494", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm des AUTOSAR-BSW-Konfigurationsmetamodells (ECUC Parameter Configuration Definition gem. <em>AUTOSAR Generic Structure Template</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Modul <strong>SwCluC</strong> (<em>Software Cluster Connection</em>, SWS Release R22-11). Das Modul ermöglicht die Entkopplung und unabhängige Aktualisierbarkeit von Software Clustern (SWC-Gruppierungen/Partitionen) auf einem Classic-AUTOSAR-Steuergerät.</li>\n<li><strong>Technischer Zweck:</strong> Definition der Metamodell-Struktur für Initialisierungs-Events (<code>SwCluCOsProxyDispatcherInitEvent</code>) innerhalb eines OS-Proxy-Task-Dispatchers (<code>SwCluCOsProxyOsTaskDispatcher</code>). Der Dispatcher verarbeitet clusterübergreifende Task- und Event-Aktivierungen über OS-Application- bzw. Speichergrenzen hinweg.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten & Metaklassen:</strong></li>\n<li><strong><code>SwCluCOsProxyOsTaskDispatcher</code></strong> (<code>EcucParamConfContainerDef</code>):</li>\n<li><em>Rolle:</em> Übergeordneter Konfigurationscontainer (Parent). Repräsentiert die Konfigurationsparameter eines dedizierten OS-Tasks, der als Dispatcher für OS-Proxy-Dienste eines Software Clusters fungiert.</li>\n<li><em>Multiplizität:</em> <code>0..*</code> (Optional; mehrere Dispatcher pro ECU/Cluster-Instanz konfigurierbar, z. B. je OS-Application, Core oder Prioritätsebene).</li>\n<li><strong><code>SwCluCOsProxyDispatcherInitEvent</code></strong> (<code>EcucParamConfContainerDef</code>, SWS-ID: <code>ECUC_SwCluC_00153</code>):</li>\n<li><em>Rolle:</em> Untergeordneter Parameter-Container (Child/Subcontainer). Spezifiziert konkrete Initialisierungs-Events, auf die der Proxy-Dispatcher-Task bei System-/Cluster-Start wartet oder die er zur Synchronisation nutzt.</li>\n<li><em>Multiplizität:</em> <code>0..*</code> (Optional; ein Dispatcher kann null, ein oder mehrere Initialisierungs-Events besitzen).</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li><strong>Komposition (<code>+subContainer</code>):</strong> Strenge Existenzabhängigkeit (gefüllte Raute am Container <code>SwCluCOsProxyOsTaskDispatcher</code>). Instanzen von <code>SwCluCOsProxyDispatcherInitEvent</code> existieren ausschließlich im Kontext ihres übergeordneten Dispatcher-Containers und werden mit diesem instanziiert bzw. verworfen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein statisches Konfigurationsmetamodell. Daraus resultiert folgender deterministischer Laufzeitablauf:</p>\n<ol class=\"fig-list\">\n<li><strong>Boot-/Lifecycle-Trigger:</strong> Das Lifecycle-Management (z. B. <code>BswM</code> oder cluster-spezifischer Startcode) startet den Software Cluster und aktiviert den zugeordneten <code>SwCluCOsProxyOsTaskDispatcher</code>.</li>\n<li><strong>Initialisierungs-Synchronisation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Dispatcher-Task blockiert initial in einem <code>WaitEvent(...)</code> auf die über <code>SwCluCOsProxyDispatcherInitEvent</code> konfigurierten Event-Masken.</li>\n<li>Das System (z. B. EcuM, BswM oder der Host-/Master-Cluster) signalisiert die Betriebsbereitschaft der zugrunde liegenden Inter-Cluster-Kommunikationsinfrastruktur (Shared RAM, Mailboxen, OS-Puffer) via <code>SetEvent(...)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dispatch-Freigabe:</strong> Nach Empfang und Validierung des/der Init-Events verlässt der Task den Initialisierungszustand, quittiert das Event (<code>ClearEvent(...)</code>) und wechselt in die operative Dispatching-Schleife zur Weiterleitung von Proxy-Requests an die lokalen Tasks des Ziel-Clusters.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfiguration (ECUC):</strong></li>\n<li>Entwickler müssen sicherstellen, dass jedes über <code>ECUC_SwCluC_00153</code> konfigurierte Init-Event auf ein gültiges <code>OsEvent</code> referenziert, das im korrespondierenden <code>OsTask</code> (dem Dispatcher) im OS-Modul (<code>Os.epc</code>) deklariert ist.</li>\n<li>Eine Multiplizität von <code>0</code> bei <code>SwCluCOsProxyDispatcherInitEvent</code> impliziert, dass der Dispatcher-Task entweder sofort nach <code>ActivateTask()</code> unkonditioniert startfähig ist oder über alternative BswM-Actions gesteuert wird.</li>\n<li><strong>Task-Klassifikation & Ressourceneffizienz:</strong></li>\n<li>Die Verwendung von Events erfordert zwingend einen <strong>Extended Task</strong> im AUTOSAR OS für den Dispatcher (<code>WaitEvent()</code> / <code>SetEvent()</code>). Bei ressourcenkritischen Systemen (RAM-Bedarf für Task-Stacks) ist zu prüfen, ob auf Init-Events verzichtet werden kann, um den Dispatcher als <strong>Basic Task</strong> auszuführen.</li>\n<li><strong>Cluster-Entkopplung & Safety:</strong></li>\n<li>Das Init-Event dient als Barriere gegen Race Conditions beim asynchronen Booten heterogener Software Cluster: Der Proxy-Task nimmt keine operativen Inter-Cluster-Aufrufe entgegen, bevor die durch <code>SwCluCOsProxyDispatcherInitEvent</code> definierte Vorbedingung erfüllt ist.</li>\n</ul>"}, {"id": "FIG-1131ecd6e8753ccb", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm des AUTOSAR-BSW-Konfigurationsmetamodells (ECUC Parameter Configuration Definition gem. <em>AUTOSAR Generic Structure Template</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Modul <strong>SwCluC</strong> (<em>Software Cluster Connection</em>, SWS Release R22-11). Das Modul ermöglicht die Entkopplung und unabhängige Aktualisierbarkeit von Software Clustern (SWC-Gruppierungen/Partitionen) auf einem Classic-AUTOSAR-Steuergerät.</li>\n<li><strong>Technischer Zweck:</strong> Definition der Metamodell-Struktur für Initialisierungs-Events (<code>SwCluCOsProxyDispatcherInitEvent</code>) innerhalb eines OS-Proxy-Task-Dispatchers (<code>SwCluCOsProxyOsTaskDispatcher</code>). Der Dispatcher verarbeitet clusterübergreifende Task- und Event-Aktivierungen über OS-Application- bzw. Speichergrenzen hinweg.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten & Metaklassen:</strong></li>\n<li><strong><code>SwCluCOsProxyOsTaskDispatcher</code></strong> (<code>EcucParamConfContainerDef</code>):</li>\n<li><em>Rolle:</em> Übergeordneter Konfigurationscontainer (Parent). Repräsentiert die Konfigurationsparameter eines dedizierten OS-Tasks, der als Dispatcher für OS-Proxy-Dienste eines Software Clusters fungiert.</li>\n<li><em>Multiplizität:</em> <code>0..1</code> (Optional; maximal ein Dispatcher pro Software-Cluster-Kontext konfigurierbar).</li>\n<li><strong><code>SwCluCOsProxyDispatcherInitEvent</code></strong> (<code>EcucParamConfContainerDef</code>, SWS-ID: <code>ECUC_SwCluC_00153</code>):</li>\n<li><em>Rolle:</em> Untergeordneter Parameter-Container (Child/Subcontainer). Spezifiziert konkrete Initialisierungs-Events, auf die der Proxy-Dispatcher-Task bei System-/Cluster-Start wartet oder die er zur Synchronisation nutzt.</li>\n<li><em>Multiplizität:</em> <code>0..*</code> (Optional; ein Dispatcher kann null, ein oder mehrere Initialisierungs-Events besitzen).</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li><strong>Komposition (<code>+subContainer</code>):</strong> Strenge Existenzabhängigkeit (gefüllte Raute am Container <code>SwCluCOsProxyOsTaskDispatcher</code>). Instanzen von <code>SwCluCOsProxyDispatcherInitEvent</code> existieren ausschließlich im Kontext ihres übergeordneten Dispatcher-Containers und werden mit diesem instanziiert bzw. verworfen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein statisches Konfigurationsmetamodell. Daraus resultiert folgender deterministischer Laufzeitablauf:</p>\n<ol class=\"fig-list\">\n<li><strong>Boot-/Lifecycle-Trigger:</strong> Das Lifecycle-Management (z. B. <code>BswM</code> oder cluster-spezifischer Startcode) startet den Software Cluster und aktiviert den zugeordneten <code>SwCluCOsProxyOsTaskDispatcher</code>.</li>\n<li><strong>Initialisierungs-Synchronisation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Dispatcher-Task blockiert initial in einem <code>WaitEvent(...)</code> auf die über <code>SwCluCOsProxyDispatcherInitEvent</code> konfigurierten Event-Masken.</li>\n<li>Das System (z. B. EcuM, BswM oder der Host-/Master-Cluster) signalisiert die Betriebsbereitschaft der zugrunde liegenden Inter-Cluster-Kommunikationsinfrastruktur (Shared RAM, Mailboxen, OS-Puffer) via <code>SetEvent(...)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dispatch-Freigabe:</strong> Nach Empfang und Validierung des/der Init-Events verlässt der Task den Initialisierungszustand, quittiert das Event (<code>ClearEvent(...)</code>) und wechselt in die operative Dispatching-Schleife zur Weiterleitung von Proxy-Requests an die lokalen Tasks des Ziel-Clusters.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfiguration (ECUC):</strong></li>\n<li>Entwickler müssen sicherstellen, dass jedes über <code>ECUC_SwCluC_00153</code> konfigurierte Init-Event auf ein gültiges <code>OsEvent</code> referenziert, das im korrespondierenden <code>OsTask</code> (dem Dispatcher) im OS-Modul (<code>Os.epc</code>) deklariert ist.</li>\n<li>Eine Multiplizität von <code>0</code> bei <code>SwCluCOsProxyDispatcherInitEvent</code> impliziert, dass der Dispatcher-Task entweder sofort nach <code>ActivateTask()</code> unkonditioniert startfähig ist oder über alternative BswM-Actions gesteuert wird.</li>\n<li><strong>Task-Klassifikation & Ressourceneffizienz:</strong></li>\n<li>Die Verwendung von Events erfordert zwingend einen <strong>Extended Task</strong> im AUTOSAR OS für den Dispatcher (<code>WaitEvent()</code> / <code>SetEvent()</code>). Bei ressourcenkritischen Systemen (RAM-Bedarf für Task-Stacks) ist zu prüfen, ob auf Init-Events verzichtet werden kann, um den Dispatcher als <strong>Basic Task</strong> auszuführen.</li>\n<li><strong>Cluster-Entkopplung & Safety:</strong></li>\n<li>Das Init-Event dient als Barriere gegen Race Conditions beim asynchronen Booten heterogener Software Cluster: Der Proxy-Task nimmt keine operativen Inter-Cluster-Aufrufe entgegen, bevor die durch <code>SwCluCOsProxyDispatcherInitEvent</code> definierte Vorbedingung erfüllt ist.</li>\n</ul>"}], "trans": [{"from": "FIG-7c972a368adf454d", "to": "FIG-d82dd86b4ae023d8", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d82dd86b4ae023d8", "to": "FIG-efdb383101a27494", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-efdb383101a27494", "to": "FIG-1131ecd6e8753ccb", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>SwCluCOsProxyOsTaskDispatcher</code>: Die obere Multiplizität (<code>upperMultiplicity</code>) wurde von <code><em></code> auf <code>1</code> geändert (Multiplizität nun <code>0..1</code> statt <code>0..</em></code>).</li>\n</ul>"}]};
